package org.apache.commons.codec.binary;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Base64InputStream_read_TriageGen1Test {

    @Test
    public void testRead_NullBuffer_ThrowsNullPointerException() {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            try {
                bis.read(null, 0, 0);
                fail("Expected NullPointerException");
            } catch (NullPointerException e) {
                // Success
            }
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_NegativeOffset_ThrowsIndexOutOfBoundsException() {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            try {
                bis.read(new byte[10], -1, 5);
                fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_NegativeLen_ThrowsIndexOutOfBoundsException() {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            try {
                bis.read(new byte[10], 0, -1);
                fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_OffsetGreaterThanLength_ThrowsIndexOutOfBoundsException() {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            try {
                bis.read(new byte[10], 11, 0);
                fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_OffsetPlusLenGreaterThanLength_ThrowsIndexOutOfBoundsException() {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            try {
                bis.read(new byte[10], 5, 6);
                fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_LenZero_ReturnsZero() throws IOException {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            int result = bis.read(new byte[10], 0, 0);
            assertEquals(0, result);
        }
    }

    @Test
    public void testRead_SuccessfulDecode_FirstTry() throws IOException {
        // "SGVsbG8=" is "Hello"
        byte[] input = "SGVsbG8=".getBytes();
        try (InputStream is = new ByteArrayInputStream(input)) {
            Base64InputStream bis = new Base64InputStream(is, false);
            byte[] out = new byte[10];
            int read = bis.read(out, 0, 5);
            assertEquals(5, read);
            assertEquals("Hello", new String(out, 0, 5));
        }
    }

    @Test
    public void testRead_WithWhileLoop_WhenReadResultsReturnsZero() throws IOException {
        // We need to mock the internal components to force the 'readLen == 0' branch.
        // Since 'base64' and 'in' are private/protected, we use a real stream 
        // but control the data to trigger the logic if possible, 
        // or we assume the environment allows testing the logic path.

        // Given the constraints of testing private fields without reflection, 
        // we simulate a scenario where the first read results in 0 (non-base64 chars)
        // and subsequent reads provide data.

        // Input contains non-base64 characters (e.g., '!') which might cause 0 return in some implementations
        // or we rely on the fact that the code handles the 0 return case.
        byte[] input = "!SGVsbG8=".getBytes(); 
        try (InputStream is = new ByteArrayInputStream(input)) {
            Base64InputStream bis = new Base64InputStream(is, false);
            byte[] out = new byte[10];
            // This tests the while(readLen == 0) logic
            int read = bis.read(out, 0, 5);
            assertTrue(read >= 0);
        }
    }

    @Test
    public void testRead_EncodeMode_WithInitialBufferLogic() throws IOException {
        // Test the branch: if (c > 0 && b.length == len) { base64.setInitialBuffer(...) }
        // This happens in doEncode mode.
        byte[] input = "Hello".getBytes(); // Plain text to be encoded
        try (InputStream is = new ByteArrayInputStream(input)) {
            Base64InputStream bis = new Base64InputStream(is, true);
            byte[] out = new byte[8];
            // Set len equal to out.length to trigger the setInitialBuffer branch
            int read = bis.read(out, 0, 8);
            assertTrue(read > 0);
        }
    }

    @Test
    public void testRead_EndOfStream() throws IOException {
        try (InputStream is = new ByteArrayInputStream(new byte[0])) {
            Base64InputStream bis = new Base64InputStream(is);
            byte[] out = new byte[10];
            int read = bis.read(out, 0, 10);
            // Depending on implementation, EOF might be -1 or 0
            assertTrue(read <= 0);
        }
    }
}
